package main
import("crypto";"crypto/rsa";"crypto/sha256";"crypto/x509";"encoding/pem";"fmt";"os")
func main(){cert,e:=os.ReadFile(os.Args[1]);if e!=nil{panic(e)};p,_:=pem.Decode(cert);c,e:=x509.ParseCertificate(p.Bytes);if e!=nil{panic(e)};key,ok:=c.PublicKey.(*rsa.PublicKey);if !ok{panic("not RSA")};digest:=sha256.Sum256([]byte("credential-concurrency-fixture"));for _,path:=range os.Args[2:]{sig,e:=os.ReadFile(path);if e!=nil{panic(e)};if e=rsa.VerifyPSS(key,crypto.SHA256,digest[:],sig,&rsa.PSSOptions{SaltLength:32,Hash:crypto.SHA256});e!=nil{panic(e)}};fmt.Printf("Go verified %d RSA-PSS signatures with 32-byte salt\n",len(os.Args)-2)}
